      const front = n.sprite.startsWith("CIV") ? "CIV1" : n.sprite.startsWith("COP") ? "COP1" : "POL1", back = front === "CIV1" ? "CIV2" : front === "COP1" ? "COP2" : "POL2";
      drawNpcSprite(state.player.y < n.y - 35 ? back : front, n.x, n.y, 1.03);
