  function drawNavigator() {
    const ob = localObjective();
    if (!ob) return;
    const x = ob.x - camera.x, y = ob.y - camera.y;
    if (x > 55 && x < W - 55 && y > 125 && y < WORLD_VIEW_H - 35) return;
    const dx = x - W / 2, dy = y - 320, k = Math.min(
      570 / Math.max(1, Math.abs(dx)),
      180 / Math.max(1, Math.abs(dy))
    ), sx = W / 2 + dx * k, sy = 320 + dy * k;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(Math.atan2(dy, dx));
    ctx.fillStyle = "#ffdf8c";
    ctx.beginPath();
    ctx.moveTo(13, 0);
    ctx.lineTo(-8, -8);
    ctx.lineTo(-8, 8);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
